const doc = $('טריגר - חשבונית חדשה (מ-WF1)').item.json;
const lead = $json;
const customerEmail = (lead && lead.fields && lead.fields.Email) ? lead.fields.Email : null;

const today = new Date().toLocaleDateString('he-IL');
const amount = Number(doc.Amount) || 0;
const vat = Number(doc.VatAmount) || 0;
const total = Number(doc.Total) || 0;

const html = '<div style="font-family:Arial,sans-serif;direction:rtl;max-width:600px;margin:auto;border:1px solid #e0e0e0;padding:24px;border-radius:8px;">' +
  '<h2 style="color:#1a73e8;margin-bottom:4px;">איי.איי אלקטרוניקה</h2>' +
  '<p style="color:#666;margin-top:0;">חשבונית מס / קבלה</p>' +
  '<hr style="border:none;border-top:1px solid #eee;margin:16px 0;">' +
  '<table style="width:100%;font-size:14px;">' +
  '<tr><td style="padding:4px 0;color:#666;">מספר חשבונית:</td><td style="text-align:left;font-weight:bold;">' + (doc.InvoiceNumber || '') + '</td></tr>' +
  '<tr><td style="padding:4px 0;color:#666;">תאריך:</td><td style="text-align:left;">' + today + '</td></tr>' +
  '<tr><td style="padding:4px 0;color:#666;">לקוח:</td><td style="text-align:left;">' + (doc.CustomerId || 'לא צוין') + '</td></tr>' +
  '</table>' +
  '<hr style="border:none;border-top:1px solid #eee;margin:16px 0;">' +
  '<table style="width:100%;font-size:14px;">' +
  '<tr><td style="padding:4px 0;">סכום לפני מע"מ</td><td style="text-align:left;">₪' + amount.toFixed(2) + '</td></tr>' +
  '<tr><td style="padding:4px 0;">מע"מ (18%)</td><td style="text-align:left;">₪' + vat.toFixed(2) + '</td></tr>' +
  '<tr style="font-weight:bold;font-size:16px;"><td style="padding:8px 0;border-top:1px solid #eee;">סה"כ לתשלום</td><td style="text-align:left;padding:8px 0;border-top:1px solid #eee;">₪' + total.toFixed(2) + '</td></tr>' +
  '</table>' +
  '<p style="margin-top:24px;color:#666;font-size:13px;">תודה שקניתם אצלנו!<br>בברכה, צוות איי.איי אלקטרוניקה</p>' +
  '</div>';

return {
  json: {
    invoiceNumber: doc.InvoiceNumber,
    customerId: doc.CustomerId,
    recordId: doc.recordId,
    customerEmail,
    htmlContent: html
  }
};

